#!/usr/bin/env python3
"""Modern climate data analysis script for Python 3."""

from __future__ import annotations

import configparser
from pathlib import Path

import pandas as pd


BASE_DIR = Path(__file__).resolve().parent
CONFIG_PATH = BASE_DIR / "climate_analyzer" / "config.ini"
DATA_PATH = BASE_DIR / "climate_analyzer" / "sample_data" / "climate_data.csv"


class ClimateAnalyzer:
    """Load climate station data and report mean temperatures."""

    def __init__(self, config_path: Path = CONFIG_PATH, data_path: Path = DATA_PATH) -> None:
        self.config_path = Path(config_path)
        self.data_path = Path(data_path)
        self.config = configparser.ConfigParser()
        self.config.read(self.config_path, encoding="utf-8")

    def load_temperature_data(self) -> pd.DataFrame:
        """Read climate observations from CSV using UTF-8 encoding."""
        return pd.read_csv(
            self.data_path,
            encoding="utf-8",
            parse_dates=["date"],
        )

    def mean_temperatures_by_station(self) -> pd.Series:
        """Calculate mean temperature for each station in the data set."""
        data = self.load_temperature_data()
        return data.groupby("station_id", sort=True)["temperature"].mean()

    def run_analysis(self) -> None:
        """Print station mean temperatures in the required format."""
        for station_id, mean_temperature in self.mean_temperatures_by_station().items():
            print(f"Station {station_id} mean temperature: {mean_temperature:.1f}°C")


if __name__ == "__main__":
    ClimateAnalyzer().run_analysis()

